UPDATE `product` SET `detail` = '## 产品简介\n挪威进口新鲜三文鱼，产自北大西洋寒冷深海水域，全程冷链运输，48小时内送达。肉质鲜嫩橙红，入口即化，是刺身、寿司的顶级食材。\n\n## 产品特点\n- **产地直供**：挪威北大西洋认证海域\n- **Omega-3丰富**：每100g含2.5g优质Omega-3脂肪酸\n- **无激素无抗生素**：通过欧盟ASC可持续水产认证\n- **全程冷链**：0~4°C低温运输，保鲜不失味\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 20g |\n| 脂肪 | 13g（富含Omega-3） |\n| 维生素D | 447IU |\n| 钙 | 12mg |\n\n## 烹饪建议\n**刺身**：切3-4mm薄片，搭配芥末和日式酱油，原味最佳\n\n**香煎**：平底锅热油，皮朝下煎3分钟，翻面再煎2分钟，撒黑胡椒\n\n**烤箱**：180°C烤15分钟，搭配柠檬黄油酱\n\n## 储存说明\n- 冷冻保存：-18°C以下，可保存30天\n- 解冻后请于24小时内食用\n- 建议流水缓慢解冻，保留最佳口感' WHERE id = 1;

UPDATE `product` SET `detail` = '## 产品简介\n大连野生鲍鱼，生长于黄渤海交汇处，水质清澈，水温适宜，养殖期长达3年以上。肉质肥厚紧实，鲜味浓郁，自古被列为海八珍之首。\n\n## 产品特点\n- **野生品质**：大连长海县纯野生捕捞，肉质优于养殖\n- **个大肉厚**：单只净重约80g，头数规格饱满\n- **活体发货**：充氧保活包装，确保鲜活到家\n- **营养丰富**：富含蛋白质、牛磺酸及多种微量元素\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 12.6g |\n| 脂肪 | 0.8g |\n| 碘 | 丰富 |\n| 维生素E | 2.4mg |\n\n## 烹饪建议\n**清蒸鲍鱼**：处理干净后，加生姜、葱、蒸鱼豉油，大火蒸8分钟\n\n**蒜蓉鲍鱼**：壳面铺蒜蓉，淋热油激香，加蒸鱼豉油即可\n\n**红烧鲍鱼**：配五花肉、老抽、料酒小火慢烧，色泽红亮\n\n## 储存说明\n- 收到后请尽快食用，活鲍鱼冷藏可存放1-2天\n- 煮熟后冷藏保存不超过2天\n- 切勿放入淡水中，会导致死亡' WHERE id = 2;

UPDATE `product` SET `detail` = '## 产品简介\n正宗波士顿龙虾，产自美国东北部大西洋海域，鲜活空运直达。龙虾体型硕大，两只巨螯肉质丰厚，虾肉鲜甜弹牙，是高端宴席的明星食材。\n\n## 产品特点\n- **鲜活空运**：产地直采，航空冷链，到货存活率99%\n- **体型标准**：单只约700g，肉量充足\n- **双螯丰满**：波士顿龙虾独有大螯，螯肉鲜甜\n- **无污染海域**：产自北大西洋清洁冷水海域\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 18.8g |\n| 脂肪 | 1.9g |\n| 钙 | 60mg |\n| 锌 | 2.8mg |\n\n## 烹饪建议\n**白灼**：整只放入沸腾盐水中煮12分钟，搭配黄油蒜蓉蘸酱\n\n**蒜蓉芝士焗龙虾**：从背部剖开，铺蒜蓉奶酪，200°C烤12分钟\n\n**龙虾刺身**：活杀取尾肉，切片直接食用，鲜甜无比\n\n## 储存说明\n- 鲜活龙虾收到后请立即烹饪\n- 若暂时不烹饪，可用湿毛巾包裹放冰箱冷藏，存活不超过24小时\n- 煮熟后冷藏保存不超过2天' WHERE id = 3;

UPDATE `product` SET `detail` = '## 产品简介\n深海野生金枪鱼，产自太平洋深远洋海域，由专业远洋渔船捕捞后立即急冻处理。肉质鲜红紧实，脂肪均匀分布，是日式刺身料理中最受欢迎的鱼种之一。\n\n## 产品特点\n- **深海野生捕捞**：太平洋深远洋，无污染纯净水域\n- **急冻锁鲜**：捕捞后-60°C超低温急冻，最大限度保留鲜味\n- **肉色鲜红**：高DHA含量使肉色深红，口感细腻\n- **刺身级品质**：达到日本刺身用鱼卫生标准\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 23.3g |\n| DHA | 1.7g |\n| EPA | 0.9g |\n| 维生素B12 | 9.4μg |\n\n## 烹饪建议\n**刺身**：半解冻状态下切3-5mm薄片，搭配山葵和日式酱油\n\n**金枪鱼手卷**：切丁配黄瓜丝、牛油果、寿司醋饭\n\n**香煎金枪鱼排**：表面撒盐和黑胡椒，大火两面各煎1分钟，保留粉红色内芯\n\n## 储存说明\n- -18°C以下冷冻保存，保质期20天\n- 刺身用途建议解冻后4小时内食用\n- 请勿反复冷冻解冻' WHERE id = 4;

UPDATE `product` SET `detail` = '## 产品简介\n东海野生黄花鱼，又称大黄鱼，产自浙江舟山渔场。肉质细嫩洁白，鱼鳞金黄，无腥味，是清蒸、红烧的绝佳食材，深受家庭厨房喜爱。\n\n## 产品特点\n- **东海野生**：舟山渔场纯野生捕捞，非人工养殖\n- **新鲜速冻**：捕捞当天处理急冻，保留鲜活风味\n- **少刺易食**：刺骨分布规律，适合老人和儿童\n- **低脂高蛋白**：适合减脂增肌人群食用\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 17.7g |\n| 脂肪 | 2.5g |\n| 钙 | 53mg |\n| 硒 | 42.6μg |\n\n## 烹饪建议\n**清蒸黄花鱼**：鱼背划刀，铺姜丝葱段，大火蒸10分钟，淋豉油热油\n\n**红烧黄花鱼**：两面煎至金黄，加豆瓣酱、酱油、糖慢烧\n\n**黄花鱼汤**：加豆腐、嫩姜，小火煮20分钟，汤色奶白鲜甜\n\n## 储存说明\n- 冷藏保存：0~4°C，保存3天内食用\n- 冷冻保存：-18°C，可保存30天\n- 解冻后不建议再次冷冻' WHERE id = 5;

UPDATE `product` SET `detail` = '## 产品简介\n舟山带鱼，来自中国最优质的带鱼产区。肉质肥美雪白，鱼鳞富含不饱和脂肪酸，红烧、清蒸、酥炸均可，是中国家庭餐桌上最受欢迎的海鱼之一。\n\n## 产品特点\n- **舟山原产**：东海带鱼核心产区，品质优于其他产地\n- **肉厚脂肪丰**：腹部银白，背部肥厚，口感鲜美\n- **整条速冻**：新鲜处理后整条急冻，锁住鲜味\n- **高性价比**：经济实惠，全年可购\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 18.1g |\n| 脂肪 | 7.4g |\n| 钙 | 28mg |\n| 磷 | 191mg |\n\n## 烹饪建议\n**红烧带鱼**：两面煎至金黄，加酱油、醋、糖、葱姜蒜炖10分钟，经典家常做法\n\n**清蒸带鱼**：铺葱姜，大火蒸8分钟，淋豉油热油，清淡鲜美\n\n**椒盐酥炸带鱼**：裹面粉炸至金黄，撒椒盐，外酥里嫩\n\n## 储存说明\n- -18°C以下冷冻保存，保质期60天\n- 解冻后请当天食用\n- 解冻时可用冷水浸泡20分钟' WHERE id = 6;

UPDATE `product` SET `detail` = '## 产品简介\n广东鲜活鲈鱼，在清洁水体中养殖，肉质鲜嫩细腻，几乎无腥味。鱼刺少，适合各年龄段食用，清蒸是最能体现其鲜美的烹饪方式。\n\n## 产品特点\n- **鲜活发货**：充氧保活运输，确保到家鲜活\n- **肉质细嫩**：纤维细腻，无土腥味，老人儿童皆宜\n- **刺少易食**：主刺清晰，食用方便\n- **低脂高蛋白**：每100g蛋白质含量高达18.6g\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 18.6g |\n| 脂肪 | 3.4g |\n| 维生素A | 19μg |\n| 钙 | 138mg |\n\n## 烹饪建议\n**清蒸鲈鱼**：鱼身划斜刀，铺姜丝葱丝，大火蒸8-10分钟，淋蒸鱼豉油和热油\n\n**红烧鲈鱼**：两面煎黄，加豆瓣酱、酱油红烧8分钟，鱼香浓郁\n\n**鲈鱼汤**：加嫩豆腐、枸杞、姜片，小火煮20分钟，滋补暖胃\n\n## 储存说明\n- 鲜活到家后建议当天烹饪\n- 若需存放，可在鱼桶中暂养，不超过24小时\n- 宰杀后冷藏保存不超过2天' WHERE id = 7;

UPDATE `product` SET `detail` = '## 产品简介\n南海深海石斑鱼，生活于珊瑚礁附近，以小鱼小虾为食。肉质厚实Q弹，皮胶丰富，味道鲜甜，是粤港澳高档海鲜食府的必备食材。\n\n## 产品特点\n- **深海品质**：南海深海石斑，肉质紧实Q弹\n- **皮胶丰富**：皮下含大量胶原蛋白，美容养颜\n- **鲜活速冻**：宰杀处理后急冻，最大程度保鲜\n- **高档食材**：粤菜酒楼指定食材，品质可靠\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 19.8g |\n| 脂肪 | 2.1g |\n| 胶原蛋白 | 丰富 |\n| 锌 | 1.2mg |\n\n## 烹饪建议\n**清蒸石斑**：整鱼铺姜丝葱段，猛火蒸10-12分钟，淋生抽麻油\n\n**豉汁蒸石斑**：用豆豉、蒜末、辣椒调制豉汁，浇在鱼上蒸制\n\n**石斑鱼火锅**：切片涮火锅，入口鲜甜Q弹，搭配沙茶酱\n\n## 储存说明\n- -18°C以下冷冻保存，保质期30天\n- 解冻后请于24小时内食用\n- 建议冰箱冷藏缓慢解冻，保留最佳口感' WHERE id = 8;

UPDATE `product` SET `detail` = '## 产品简介\n阿拉斯加野生鳕鱼，产自北太平洋清洁寒冷海域。肉质雪白细嫩，富含DHA，几乎无刺，是儿童辅食和老人补充蛋白质的理想选择。\n\n## 产品特点\n- **阿拉斯加野生**：全球最优质鳕鱼产区，无污染\n- **雪白肉质**：低脂肪，肉色洁白，口感细嫩\n- **几乎无刺**：适合儿童、老人食用\n- **MSC认证**：通过海洋管理委员会可持续渔业认证\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 17.4g |\n| 脂肪 | 0.5g |\n| DHA | 860mg |\n| 维生素B12 | 0.9μg |\n\n## 烹饪建议\n**香煎鳕鱼**：腌制15分钟，厨房纸吸干水分，平底锅热油两面各煎3分钟，外酥里嫩\n\n**清蒸鳕鱼**：铺姜丝，大火蒸8分钟，淋豉油热油，清淡鲜嫩\n\n**鳕鱼粥**：鳕鱼片与大米同煮，加姜丝、葱花，营养丰富适合老幼\n\n## 储存说明\n- -18°C以下冷冻保存，保质期90天\n- 解冻后请于当天食用\n- 解冻可用冰箱冷藏过夜缓慢解冻' WHERE id = 9;

