UPDATE `product` SET `detail` = '## 产品简介\n阳澄湖正宗大闸蟹，产自被誉为中国蟹都的苏州阳澄湖。每年9-10月金秋时节上市，膏肥黄满，蟹味浓郁，是送礼、家宴的顶级食材。\n\n## 产品特点\n- **阳澄湖正宗**：带防伪溯源码，可扫码验真伪\n- **金秋时令**：9月雌蟹黄多，10月雄蟹膏满\n- **活体发货**：专用扎绳保活包装，存活率保证\n- **礼盒装**：精美礼盒附送食蟹工具，送礼体面\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 15.9g |\n| 蟹黄胆固醇 | 较高 |\n| 锌 | 3.6mg |\n| 维生素A | 389μg |\n\n## 烹饪建议\n**清蒸大闸蟹**：螃蟹腹部朝上冷水下锅，水开后蒸15-18分钟，搭配姜末香醋蘸食\n\n**醉蟹**：活蟹浸泡于黄酒、盐、香料中腌制24小时，生食风味独特\n\n**蟹粉豆腐**：取蟹黄蟹肉炒制，与嫩豆腐同烩，鲜味十足\n\n## 储存说明\n- 活蟹收到后尽快食用，最多冷藏暂养2天\n- 螃蟹对淡水敏感，保存时不可浸水\n- 死蟹不可食用，请及时处理' WHERE id = 11;

UPDATE `product` SET `detail` = '## 产品简介\n山东荣成新鲜扇贝，产自北黄海优质养殖区，海水清洁，水温适宜。贝柱肥厚鲜甜，外壳美观，无论蒸煮还是烧烤，鲜味十足。\n\n## 产品特点\n- **山东原产**：荣成贝类养殖重要基地，品质上乘\n- **贝柱饱满**：肉质肥厚，鲜味浓郁\n- **新鲜速冻**：捕捞后24小时内处理急冻\n- **洗净去沙**：去除肠线和沙砾，食用便捷\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 17.0g |\n| 脂肪 | 0.4g |\n| 锌 | 11.7mg |\n| 维生素B12 | 1.1μg |\n\n## 烹饪建议\n**蒜蓉粉丝蒸扇贝**：铺泡软粉丝，加蒜蓉、生抽，大火蒸5分钟，淋热油激香\n\n**黄油煎扇贝**：贝柱取出，黄油大火煎1分钟，两面金黄，撒黑胡椒\n\n**烧烤扇贝**：整壳摆炭火上，放黄油蒜蓉，烤至汤汁翻滚即可\n\n## 储存说明\n- -18°C以下冷冻保存，保质期30天\n- 解冻后请于当天食用\n- 鲜活扇贝冷藏保存不超过2天' WHERE id = 12;

UPDATE `product` SET `detail` = '## 产品简介\n山东乳山生蚝，产自黄海乳山湾，素有中国生蚝之乡美誉。个大肥美，肉质饱满，牛磺酸和锌含量极高，是补充锌元素的优质天然食材。\n\n## 产品特点\n- **乳山认证**：乳山生蚝国家地理标志产品\n- **个大肥美**：单只净肉约50-80g，肉质丰满\n- **高锌补锌**：锌含量为猪肉的5倍，男士尤为推荐\n- **鲜活直达**：充氧保活运输，保证鲜活到家\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 5.3g |\n| 锌 | 9.4mg |\n| 牛磺酸 | 丰富 |\n| 糖原 | 丰富 |\n\n## 烹饪建议\n**生食生蚝**：配柠檬汁或葡萄酒醋，生蚝刚剥开直接入口，鲜甜无比\n\n**蒜蓉蒸生蚝**：壳上放蒜蓉、粉丝、生抽，蒸5分钟，淋热油\n\n**炭烤生蚝**：直接摆炭火上，壳口朝上，放黄油和蒜末，待壳口开裂起泡即可\n\n## 储存说明\n- 鲜活生蚝冷藏保存不超过3天\n- 保存时需保持湿润，可覆盖湿布\n- 死亡的生蚝请勿食用' WHERE id = 13;

UPDATE `product` SET `detail` = '## 产品简介\n广东鲜活基围虾，产自珠三角纯净养殖基地，肉质弹牙紧实，虾壳薄软，虾味鲜甜，是白灼虾的最佳选择，也是广式海鲜餐厅的招牌食材。\n\n## 产品特点\n- **鲜活发货**：充氧保活包装，存活率高达98%\n- **肉质弹牙**：虾肉紧实有弹性，入口鲜甜\n- **虾壳薄软**：剥壳容易，食用方便\n- **无泥无腥**：水质清洁养殖，腥味极低\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 18.2g |\n| 脂肪 | 1.4g |\n| 钙 | 62mg |\n| 磷 | 228mg |\n\n## 烹饪建议\n**白灼基围虾**：沸水加姜片、料酒，放虾煮2分钟，捞出配蒜蓉酱油蘸食\n\n**椒盐虾**：裹面粉炸至金黄，加青椒、洋葱爆炒，撒椒盐\n\n**油焖大虾**：虾背划开，热油煸炒，加番茄酱、生抽、糖焖制\n\n## 储存说明\n- 活虾收到后尽量当天食用\n- 短期保存：冷藏不超过1天\n- 冷冻保存：-18°C，可保存30天' WHERE id = 14;

UPDATE `product` SET `detail` = '## 产品简介\n阿拉斯加帝王蟹，蟹中之王，体型巨大，腿长肉丰。蟹腿肉质厚实雪白，鲜甜无比，是宴席摆台的顶级食材，彰显主人的热情与品位。\n\n## 产品特点\n- **阿拉斯加正宗**：北太平洋清洁寒水，帝王蟹的理想栖息地\n- **体型庞大**：整只约2.5-3.5kg，蟹腿长达60cm\n- **蟹腿肉丰**：腿肉厚实，一只腿肉量相当于普通螃蟹全身\n- **超低温急冻**：-60°C急冻保鲜，锁住最佳风味\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 17.5g |\n| 脂肪 | 1.5g |\n| 欧米伽3 | 0.4g |\n| 硒 | 36μg |\n\n## 烹饪建议\n**清蒸帝王蟹腿**：锅内沸水，蟹腿蒸10-12分钟，配黄油柠檬蘸汁\n\n**黄油香草烤蟹腿**：剪开蟹腿背面，铺黄油蒜末香草，200°C烤10分钟\n\n**帝王蟹火锅**：蟹腿剁段，涮火锅2分钟，鲜甜爽口\n\n## 储存说明\n- -18°C以下冷冻保存，保质期30天\n- 解冻后请于当天食用\n- 建议用冷藏室缓慢解冻，保留最佳口感' WHERE id = 15;

UPDATE `product` SET `detail` = '## 产品简介\n山东威海花蛤，产自黄海潮间带，以浮游生物和有机碎屑为食。肉质鲜嫩多汁，鲜味浓郁，价格实惠，是家庭餐桌最常见的贝类之一。\n\n## 产品特点\n- **威海正产**：威海浅海花蛤，品质优质稳定\n- **肉质鲜嫩**：贝肉柔软多汁，鲜味足\n- **已吐沙处理**：买家收到后无需长时间吐沙\n- **高性价比**：贝类中最经济实惠的品种\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 7.7g |\n| 脂肪 | 0.6g |\n| 铁 | 10.9mg |\n| 维生素B12 | 22.7μg |\n\n## 烹饪建议\n**爆炒花蛤**：热锅热油，爆香姜蒜辣椒，放花蛤大火翻炒，加豆豉酱油，壳开即可\n\n**葱姜花蛤**：清水加葱姜煮开，放花蛤煮至壳开，原汤鲜美\n\n**花蛤蒸蛋**：花蛤与鸡蛋液同蒸，口感嫩滑，鲜味加倍\n\n## 储存说明\n- 鲜活花蛤冷藏保存不超过2天\n- 保存时用湿毛巾覆盖，不可浸淡水\n- 未开口的花蛤可能已死亡，请丢弃' WHERE id = 16;

UPDATE `product` SET `detail` = '## 产品简介\n渤海鲜活皮皮虾，又称琵琶虾、虾蛄，生活于渤海潮间带。肉质鲜美异常，膏脂丰满，椒盐、蒜蓉做法均大受欢迎，是沿海地区家喻户晓的海鲜美食。\n\n## 产品特点\n- **渤海原产**：渤海皮皮虾，肉质鲜嫩，膏满\n- **活体发货**：充氧保活，确保新鲜度\n- **个大饱满**：精选大规格，每只约50-80g\n- **膏黄丰满**：4-5月为最佳季节，膏脂充盈\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 16.8g |\n| 脂肪 | 2.7g |\n| 钙 | 193mg |\n| 镁 | 60mg |\n\n## 烹饪建议\n**白灼皮皮虾**：沸水加盐和姜，放虾煮5分钟，原汁原味鲜甜\n\n**椒盐皮皮虾**：中小火炸至酥脆，加葱蒜椒盐爆炒，香脆入味\n\n**蒜蓉蒸皮皮虾**：去壳剪开背部，铺蒜蓉蒸5分钟，鲜嫩入味\n\n## 储存说明\n- 活虾收到后尽量当天食用\n- 冷藏暂养不超过1天\n- 冷冻保存：-18°C，保存30天' WHERE id = 17;

UPDATE `product` SET `detail` = '## 产品简介\n加拿大进口北极贝，产自北大西洋寒冷清洁海域，是刺身料理中颇受喜爱的贝类食材。贝肉橙红色泽鲜艳，口感爽脆清甜，富含多种氨基酸，营养价值极高。\n\n## 产品特点\n- **加拿大正品**：北大西洋寒冷水域，品质保障\n- **橙红色泽**：贝肉呈天然橙红色，观感极佳\n- **爽脆口感**：入口清甜爽脆，不同于其他贝类\n- **刺身级品质**：达到日本刺身用贝类食品安全标准\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 15.4g |\n| 脂肪 | 1.0g |\n| 牛磺酸 | 丰富 |\n| 硒 | 20μg |\n\n## 烹饪建议\n**刺身**：半解冻状态直接食用，搭配日式酱油和山葵，鲜甜爽口\n\n**北极贝寿司**：半解冻后覆盖在醋饭上，外形美观口感佳\n\n**凉拌北极贝**：切丝配黄瓜、青椒，加麻油、醋、酱油凉拌\n\n## 储存说明\n- -18°C以下冷冻保存，保质期60天\n- 刺身用途解冻后2小时内食用\n- 半解冻状态最佳，口感脆嫩' WHERE id = 18;

UPDATE `product` SET `detail` = '## 产品简介\n新西兰进口青口贝，又称绿唇贻贝，产自新西兰纯净南太平洋海域。贝肉饱满鲜嫩，带有淡淡的海洋气息，蒜蓉蒸或烧烤均口感绝佳。\n\n## 产品特点\n- **新西兰进口**：南太平洋无污染清洁海域养殖\n- **绿唇认证**：正宗新西兰绿唇贻贝，品质优良\n- **肉质饱满**：贝肉肥厚，鲜味十足\n- **半壳加工**：去除一面壳，方便料理\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 11.9g |\n| Omega-3 | 0.5g |\n| 维生素B12 | 20μg |\n| 铁 | 3.4mg |\n\n## 烹饪建议\n**蒜蓉蒸青口贝**：半壳摆盘，铺蒜蓉、粉丝，淋生抽，蒸5分钟，淋热油\n\n**芝士焗青口**：铺奶酪丝，180°C烤8分钟至表面金黄\n\n**白酒蒸青口贝**：锅中黄油炒香洋葱蒜末，倒入青口和白葡萄酒，盖盖焖5分钟\n\n## 储存说明\n- -18°C以下冷冻保存，保质期30天\n- 解冻后请于当天食用\n- 未开口的贝壳不建议强行打开食用' WHERE id = 19;

UPDATE `product` SET `detail` = '## 产品简介\n海南南美白对虾，在清洁海水中养殖，肉质紧实鲜美，营养丰富。是中国最常见的养殖虾种，适合白灼、爆炒、烧烤等多种烹饪方式。\n\n## 产品特点\n- **南美白对虾**：中国市场最主流的优质养殖虾种\n- **海南养殖**：南方温暖海域，生长速度快，肉质好\n- **个头均匀**：精选规格一致的对虾，方便烹饪\n- **新鲜速冻**：养殖基地现捕现冻，全程冷链\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 18.6g |\n| 脂肪 | 0.8g |\n| 钙 | 35mg |\n| 硒 | 33.7μg |\n\n## 烹饪建议\n**蒜蓉对虾**：虾背剪开，铺蒜蓉生抽，蒸6分钟，清香鲜美\n\n**油焖大虾**：整虾热油煸炒，加番茄酱、生抽、糖焖至入味\n\n**烧烤对虾**：串签，刷油和孜然，炭火烤4-5分钟，香气扑鼻\n\n## 储存说明\n- -18°C以下冷冻保存，保质期60天\n- 解冻后请于当天食用\n- 冷藏室缓慢解冻，保留最佳鲜度' WHERE id = 20;

UPDATE `product` SET `detail` = '## 产品简介\n深海捕捞虾仁，经专业去壳去虾线处理，方便厨房直接使用。颗粒饱满，色泽粉白，鲜甜弹牙，是家庭炒菜、做饺子馅、蒸蛋的常备食材。\n\n## 产品特点\n- **深海虾仁**：南美深海捕捞，品质优于淡水虾\n- **去壳去虾线**：处理洁净，无需再行处理\n- **颗粒饱满**：个头均匀，颗粒感强\n- **锁鲜速冻**：24小时内完成处理急冻，保留鲜甜\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 18.1g |\n| 脂肪 | 0.5g |\n| 镁 | 46mg |\n| 磷 | 215mg |\n\n## 烹饪建议\n**虾仁炒蛋**：虾仁腌制后滑炒，加入炒至半熟的鸡蛋一起翻炒，鲜嫩可口\n\n**蒜蓉炒虾仁**：热油爆香蒜末，放虾仁大火翻炒，撒盐和黑胡椒\n\n**虾仁蒸饺**：虾仁剁碎与猪肉混合作为馅料，做成蒸饺，鲜嫩多汁\n\n## 储存说明\n- -18°C以下冷冻保存，保质期60天\n- 解冻后请于当天食用\n- 炒制前无需完全解冻，半解冻状态口感更弹牙' WHERE id = 21;

UPDATE `product` SET `detail` = '## 产品简介\n东海新鲜速冻墨鱼仔，整只处理，保留触须，形态完整。口感Q弹鲜嫩，墨鱼汁浓郁，是爆炒海鲜、铁板烧烤的上佳食材，深受海鲜爱好者喜爱。\n\n## 产品特点\n- **东海野生**：东海捕捞，新鲜度高\n- **整只完整**：保留触须，形态美观，适合摆盘\n- **Q弹口感**：墨鱼仔肉质厚实，咬劲十足\n- **速冻锁鲜**：捕捞后快速处理速冻，保留鲜味\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 16.8g |\n| 脂肪 | 1.5g |\n| 牛磺酸 | 丰富 |\n| 磷 | 165mg |\n\n## 烹饪建议\n**爆炒墨鱼仔**：大火热油，加姜蒜辣椒，放墨鱼仔快速爆炒，加豆豉酱调味\n\n**铁板墨鱼仔**：铁板烧热后刷油，放墨鱼仔，加蒜蓉辣椒酱翻炒\n\n**墨鱼仔串烧**：串签刷油，炭火烤4分钟，撒孜然辣椒粉\n\n## 储存说明\n- -18°C以下冷冻保存，保质期45天\n- 解冻后请于当天食用\n- 烹饪前用流水冲洗干净墨汁残留' WHERE id = 22;

UPDATE `product` SET `detail` = '## 产品简介\n正宗潮汕手打鱼丸，采用新鲜鱼肉手工捶打制成，不添加淀粉和防腐剂。Q弹爽滑，鱼鲜味足，是火锅、汤面、煮粥的经典配料，也是潮汕美食文化的代表之一。\n\n## 产品特点\n- **纯手工制作**：传统手打工艺，不含多余淀粉\n- **Q弹有嚼劲**：落地能弹起，是品质鉴定标准\n- **鱼肉含量高**：鱼肉比例超过85%，鲜味浓郁\n- **无添加剂**：不含防腐剂、色素，天然健康\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 12.8g |\n| 脂肪 | 3.2g |\n| 钙 | 28mg |\n| 钾 | 165mg |\n\n## 烹饪建议\n**火锅涮鱼丸**：沸腾锅底放入鱼丸，煮3-4分钟至浮起，蘸酱食用\n\n**番茄鱼丸汤**：番茄炒出汤汁，加水煮沸，放鱼丸煮5分钟，加盐调味\n\n**鱼丸炒蔬菜**：鱼丸对半切开，与西兰花、胡萝卜同炒，营养均衡\n\n## 储存说明\n- -18°C以下冷冻保存，保质期90天\n- 解冻后请于当天食用\n- 鱼丸无需完全解冻，可直接放入沸水中煮制' WHERE id = 23;

UPDATE `product` SET `detail` = '## 产品简介\n广东纯手工虾滑，采用新鲜对虾为主料，保留整粒虾肉颗粒感，虾味浓郁，口感细腻。是涮火锅、做丸子、包饺子的高品质食材，虾肉含量远高于市售普通虾滑。\n\n## 产品特点\n- **高虾肉含量**：虾肉比例超过90%，弹牙鲜甜\n- **整粒虾肉**：可见明显虾肉颗粒，口感真实\n- **纯手工制作**：无机器搅打，保留原始口感\n- **无防腐剂**：天然原料，不添加化学防腐剂\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 15.3g |\n| 脂肪 | 1.8g |\n| 钙 | 35mg |\n| 硒 | 28μg |\n\n## 烹饪建议\n**火锅虾滑**：用勺子挖取一勺，放入沸腾锅底，煮3分钟至变色浮起\n\n**虾滑蒸蛋**：虾滑铺在蛋液上蒸制，嫩滑鲜美\n\n**煎虾饼**：将虾滑做成圆饼状，平底锅小火煎至两面金黄\n\n## 储存说明\n- -18°C以下冷冻保存，保质期90天\n- 解冻后请于24小时内食用\n- 建议冷藏室缓慢解冻，口感更佳' WHERE id = 24;

UPDATE `product` SET `detail` = '## 产品简介\n日本风味蟹柳，采用优质鱼糜为主料，模拟蟹腿肉的纹理和口感，搭配天然蟹肉精华调味。口感鲜甜弹嫩，是日式料理、沙拉、寿司卷的必备食材之一。\n\n## 产品特点\n- **日本配方**：原版日式蟹柳制作工艺，口感正宗\n- **蟹味浓郁**：添加天然蟹肉萃取精华，蟹香自然\n- **纹理仿真**：模拟蟹腿肌肉纹理，可像真蟹肉一样撕丝\n- **开袋即食**：方便快捷，直接食用或加热均可\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 9.0g |\n| 脂肪 | 0.8g |\n| 碳水化合物 | 12.0g |\n| 钠 | 600mg |\n\n## 烹饪建议\n**沙拉蟹柳**：撕丝拌入各类蔬菜沙拉，淋沙拉酱，清爽美味\n\n**蟹柳寿司卷**：搭配黄瓜条、牛油果，卷入寿司饭团，简单好做\n\n**蟹柳炒蛋**：切段与鸡蛋一起翻炒，加盐调味，鲜甜可口\n\n## 储存说明\n- -18°C以下冷冻保存，保质期180天\n- 开袋后冷藏保存，请于3天内食用\n- 可冷食也可微波加热后食用' WHERE id = 25;

UPDATE `product` SET `detail` = '## 产品简介\n台湾风味鱼豆腐，以优质鱼糜为主料制成豆腐状方块，口感嫩滑细腻，鱼香浓郁。外观洁白如豆腐，口感介于豆腐和鱼丸之间，是火锅、关东煮的经典配菜。\n\n## 产品特点\n- **台湾配方**：传承台湾传统鱼豆腐工艺，口感正宗\n- **嫩滑细腻**：质地比普通鱼丸更柔嫩，入口即化\n- **高鱼肉比例**：鱼糜含量高，蛋白质丰富\n- **百搭食材**：适合多种烹饪场景，老少皆宜\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 10.5g |\n| 脂肪 | 4.2g |\n| 碳水化合物 | 8.0g |\n| 钠 | 550mg |\n\n## 烹饪建议\n**火锅涮鱼豆腐**：放入沸腾锅底煮3-4分钟，吸收锅底鲜味，口感绝佳\n\n**关东煮**：与萝卜、魔芋等食材一起在高汤中慢炖30分钟\n\n**香煎鱼豆腐**：平底锅加少量油，两面煎至金黄，外酥内嫩\n\n## 储存说明\n- -18°C以下冷冻保存，保质期180天\n- 解冻后请于当天食用\n- 无需完全解冻，可直接放入沸水烹饪' WHERE id = 26;

UPDATE `product` SET `detail` = '## 产品简介\n深海野生章鱼足，产自北太平洋深海，单足重量约80-120g，肉质厚实。经过简单清洁处理，保留原始鲜味，适合烧烤、爆炒、章鱼小丸子等多种做法。\n\n## 产品特点\n- **深海野生**：深海捕捞，肉质厚实鲜美\n- **独立分装**：按只计量，方便按需取用\n- **新鲜速冻**：捕捞后快速处理，锁鲜效果好\n- **吸盘完整**：吸盘保留完整，口感有嚼劲\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 18.9g |\n| 脂肪 | 1.1g |\n| 牛磺酸 | 丰富 |\n| 钾 | 292mg |\n\n## 烹饪建议\n**烧烤章鱼足**：解冻后刷油，炭火烤10-12分钟，刷甜辣烤肉酱，香气扑鼻\n\n**爆炒章鱼足**：切段大火爆炒，加姜蒜辣椒豆豉酱，镬气十足\n\n**章鱼沙拉**：煮熟切片，配芝麻菜、橄榄油、柠檬汁，地中海风味\n\n## 储存说明\n- -18°C以下冷冻保存，保质期60天\n- 烹饪前建议提前1小时用冷水解冻\n- 解冻后请于当天食用' WHERE id = 27;

UPDATE `product` SET `detail` = '## 产品简介\n福建蒲烧鳗鱼段，选用优质淡水鳗鱼，经过专业烤制和蒲烧酱汁浸泡处理。肉质肥美鲜嫩，酱香浓郁，是日式料理中最受欢迎的食材之一，可直接加热食用。\n\n## 产品特点\n- **蒲烧工艺**：传统日式蒲烧技法，炭烤后涂刷特制酱汁\n- **即热即食**：简单加热即可食用，无需复杂烹饪\n- **肥美鲜嫩**：鳗鱼脂肪丰富，肉质肥嫩口感绝佳\n- **酱汁入味**：蒲烧酱汁深入鱼肉，回味无穷\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 16.3g |\n| 脂肪 | 17.0g |\n| 维生素A | 4748μg |\n| DHA | 1.3g |\n\n## 烹饪建议\n**鳗鱼饭**：微波炉解冻加热后，铺在热腾腾的米饭上，浇上酱汁，撒山椒粉\n\n**鳗鱼手卷**：切段与黄瓜、寿司饭一起做成手卷\n\n**鳗鱼茶泡饭**：鳗鱼铺在米饭上，浇入热绿茶，日式风味茶泡饭\n\n## 储存说明\n- -18°C以下冷冻保存，保质期90天\n- 建议冷藏解冻后微波炉加热2分钟\n- 开封后请于当天食用' WHERE id = 28;

UPDATE `product` SET `detail` = '## 产品简介\n大连优质干贝，又称瑶柱，以新鲜扇贝柱为原料，经过天然晾晒或低温干燥制成。鲜味物质高度浓缩，用于煲汤或蒸饭时能极大提升菜肴鲜度。\n\n## 产品特点\n- **大连正产**：大连长海县扇贝柱制成，品质上乘\n- **鲜味浓郁**：谷氨酸和甘氨酸含量极高，天然鲜味剂\n- **传统工艺**：自然晾晒，保留最佳风味\n- **方便储存**：干制品，常温保存，使用便捷\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 55.6g |\n| 脂肪 | 2.4g |\n| 锌 | 11.7mg |\n| 碘 | 丰富 |\n\n## 烹饪建议\n**干贝蒸饭**：干贝提前泡发，与大米同蒸，饭香浓郁\n\n**干贝冬瓜汤**：干贝泡发，与冬瓜、姜片煲汤，清淡鲜甜\n\n**干贝粥**：干贝泡发，加入白粥中，提升粥的鲜味层次\n\n## 使用建议\n- 烹饪前用清水浸泡2-4小时，泡发水留用，鲜味十足\n- 常温阴凉干燥处保存，保质期12个月\n- 避免潮湿环境，防止霉变' WHERE id = 29;

UPDATE `product` SET `detail` = '## 产品简介\n深海花胶，又称鱼肚，是从鱼鳔晒干而成的名贵滋补食材，自古被列为海八珍之一。胶原蛋白含量极高，是女性美容养颜、补气益精的传统保健食品。\n\n## 产品特点\n- **胶质丰富**：胶原蛋白含量约82%，美容养颜效果显著\n- **滋补佳品**：传统中医认为花胶具有补气益精、养血益精之效\n- **天然无添加**：自然晾晒，不含任何添加剂\n- **稀缺食材**：优质花胶产量稀少，营养价值高\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 73.0g |\n| 胶原蛋白 | 约82% |\n| 脂肪 | 8.0g |\n| 钙 | 50mg |\n\n## 烹饪建议\n**花胶炖鸡汤**：花胶泡发后与整鸡、红枣、枸杞一起炖3-4小时，大补元气\n\n**花胶牛奶炖**：花胶泡发切小块，加冰糖炖煮，再加入牛奶，滋润美肤\n\n**花胶糯米粥**：花胶泡发，与糯米、花生、红枣同煮，营养丰富\n\n## 使用建议\n- 烹饪前需提前用清水浸泡8-12小时\n- 常温阴凉干燥处保存，保质期24个月\n- 泡发后冷藏保存，3天内食用' WHERE id = 30;

UPDATE `product` SET `detail` = '## 产品简介\n辽宁辽参，产自黄渤海交汇处，是中国最名贵的海参品种。刺多肉厚，营养密度极高，富含海参皂苷、胶原蛋白等珍贵营养物质，是传统滋补养生圣品。\n\n## 产品特点\n- **辽参品质**：大连、旅顺等辽宁核心产区，品质最优\n- **刺多肉厚**：辽参刺高而密，肉壁厚实，营养密度高\n- **传统加工**：盐渍晾晒传统工艺，保留天然成分\n- **溯源可查**：配有产地追溯码，品质有保障\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 50.2g |\n| 海参皂苷 | 丰富 |\n| 硫酸软骨素 | 丰富 |\n| 脂肪 | 极低（约3.4g） |\n\n## 烹饪建议\n**葱烧海参**：泡发好的海参配大葱、酱油、生抽红烧，经典鲁菜做法\n\n**海参小米粥**：海参切丁，与小米、枸杞同煮粥，适合老人和病后调养\n\n**凉拌海参**：泡发切片，配黄瓜丝，加芥末油、米醋凉拌\n\n## 使用建议\n- 泡发步骤：纯净水泡24小时→去内脏→换水再泡24-48小时\n- 常温阴凉干燥处保存，保质期24个月\n- 泡发好的海参冷藏保存，3天内食用' WHERE id = 31;

UPDATE `product` SET `detail` = '## 产品简介\n舟山鱿鱼干，产自东海最优质的鱿鱼产区，经过清洗、腌制、自然晾晒等传统工艺制成。肉质厚实，鱿鱼鲜味浓缩，是爆炒、煲汤、烧烤的上佳干货食材。\n\n## 产品特点\n- **舟山原产**：东海鱿鱼核心产区，品质卓越\n- **传统晾晒**：自然风干，保留天然鲜味\n- **肉质厚实**：片型完整，厚度均匀，口感有嚼劲\n- **无添加**：不含防腐剂和人工色素，天然健康\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 60.4g |\n| 脂肪 | 7.4g |\n| 钙 | 43mg |\n| 牛磺酸 | 丰富 |\n\n## 烹饪建议\n**爆炒鱿鱼干**：泡发后切花刀，爆炒加青椒、洋葱、豆豉，镬气十足\n\n**鱿鱼干煲汤**：与排骨、花生、莲藕同煲，汤色奶白鲜甜\n\n**烧烤鱿鱼干**：泡软后串签，刷油烤制，撒孜然辣椒粉\n\n## 使用建议\n- 烹饪前用清水浸泡2-4小时至软化\n- 常温阴凉干燥处保存，保质期12个月\n- 泡发时可加少许苏打粉，使鱿鱼更嫩滑' WHERE id = 32;

UPDATE `product` SET `detail` = '## 产品简介\n福建金钩虾米，产自福建沿海，以新鲜中小型虾为原料，经过盐水煮制、晒干而成。色泽金黄，鲜味十足，是中国厨房最常用的天然调味干货，被称为金钩正是因其色泽金黄似金钩。\n\n## 产品特点\n- **福建原产**：福建沿海优质虾米产区\n- **色泽金黄**：传统工艺晒制，色泽自然金黄\n- **鲜味浓郁**：谷氨酸含量高，天然鲜味提升剂\n- **颗粒均匀**：精选大小均匀的虾米，品质稳定\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 43.7g |\n| 钙 | 617mg |\n| 镁 | 236mg |\n| 碘 | 丰富 |\n\n## 烹饪建议\n**虾米炒青菜**：热锅爆香虾米，加入青菜翻炒，提鲜增香无需额外加味精\n\n**虾米蒸蛋**：虾米加入蛋液中同蒸，鲜味十足\n\n**虾米馄饨馅**：剁碎虾米加入猪肉馅，馄饨鲜甜美味\n\n## 使用建议\n- 可直接用于烹饪，提前温水浸泡15分钟口感更佳\n- 常温阴凉干燥处保存，保质期12个月\n- 密封保存，防潮防虫' WHERE id = 33;

UPDATE `product` SET `detail` = '## 菜品简介\n宫保鸡丁，川菜经典名菜，起源于清朝，以丁宝桢（官至太子少保即宫保）命名。麻辣鲜香，鸡肉嫩滑，花生酥脆，是最受欢迎的中式快餐菜肴之一。\n\n## 产品特点\n- **经典川味**：正宗川菜配方，麻辣适中\n- **鸡肉嫩滑**：精选鸡腿肉丁，腌制入味\n- **花生酥脆**：特制炸花生，香脆不软\n- **即开即食**：简单加热，方便快捷\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 15.2g |\n| 脂肪 | 8.4g |\n| 碳水化合物 | 6.5g |\n| 热量 | 162kcal |\n\n## 食用建议\n**配米饭**：宫保鸡丁最佳伴侣，鲜辣酱汁拌入米饭，口味绝佳\n\n**配面条**：浇在煮好的面条上，省时美味\n\n**加热方式**：微波炉加热2分钟，或锅中热油翻炒1分钟\n\n## 储存说明\n- 冷藏保存0-4°C，保质期5天\n- 冷冻保存-18°C，保质期30天\n- 建议现买现吃，口感最佳' WHERE id = 34;

UPDATE `product` SET `detail` = '## 菜品简介\n鱼香肉丝，川菜代表菜之一，虽名为"鱼香"却无鱼，是以四川泡椒、豆瓣酱调制出酸甜咸辣的特殊风味。猪肉丝嫩滑，配上木耳、笋丝，层次丰富，下饭神器。\n\n## 产品特点\n- **鱼香风味独特**：泡椒豆瓣酱调制，酸甜辣咸四味兼具\n- **猪肉嫩滑**：里脊肉丝腌制处理，口感细嫩\n- **配料丰富**：含木耳、笋丝，营养均衡\n- **川菜正宗**：四川传统烹饪工艺，风味地道\n\n## 营养价值\n| 营养成分 | 每100g含量 |\n| --- | --- |\n| 蛋白质 | 12.8g |\n| 脂肪 | 9.2g |\n| 碳水化合物 | 8.0g |\n| 热量 | 165kcal |\n\n## 食用建议\n**配米饭**：拌入白米饭，酸甜辣味让食欲大开，一碗不够吃\n\n**配米线**：浇在米线上，浓郁酱汁包裹面条，鲜美无比\n\n**家庭复原**：加少量猪油翻炒，添加新鲜木耳，还原家常鲜味\n\n## 储存说明\n- 冷藏保存0-4°C，保质期5天\n- 冷冻保存-18°C，保质期30天\n- 食用前建议用锅翻炒加热，口感更好' WHERE id = 35;
